<?php require_student(); $me = student(); $stats = db_one("SELECT COUNT(*) total, SUM(status='Pending') pending, SUM(status='In Progress') progress, SUM(status='Resolved') resolved, SUM(status='Closed') closed FROM complaints WHERE student_id = ?", 'i', [$me['id']]); $recent = db_all('SELECT c.*, ca.category_name FROM complaints c JOIN categories ca ON ca.id=c.category_id WHERE c.student_id=? ORDER BY c.created_at DESC LIMIT 5', 'i', [$me['id']]); $pageTitle='Student Dashboard'; require_once __DIR__ . '/../includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-3"><?php require __DIR__ . '/_sidebar.php'; ?></div><div class="col-lg-9"><div class="dashboard-header mb-4 d-flex flex-column flex-md-row justify-content-between align-items-md-center gap-3"><div><div class="small-muted">Good to see you, <?= e($me['name']) ?></div><h1 class="section-title mb-0">Your complaint overview</h1></div><a class="btn btn-primary" href="<?= e(url('student/submit.php')) ?>">+ Submit complaint</a></div><div class="row g-3 mb-4"><div class="col-6 col-xl-3"><div class="card stat-card"><div class="stat-label">Total</div><div class="stat-value"><?= (int)($stats['total']??0) ?></div></div></div><div class="col-6 col-xl-3"><div class="card stat-card"><div class="stat-label">Pending</div><div class="stat-value text-warning"><?= (int)($stats['pending']??0) ?></div></div></div><div class="col-6 col-xl-3"><div class="card stat-card"><div class="stat-label">In progress</div><div class="stat-value text-primary"><?= (int)($stats['progress']??0) ?></div></div></div><div class="col-6 col-xl-3"><div class="card stat-card"><div class="stat-label">Resolved</div><div class="stat-value text-success"><?= (int)($stats['resolved']??0) ?></div></div></div></div><div class="card"><div class="card-header d-flex justify-content-between"><strong>Recent complaints</strong><a href="<?= e(url('student/my-complaints.php')) ?>" class="small text-decoration-none">View all</a></div><?php if (!$recent): ?><div class="empty-state">You have not submitted any complaints yet.</div><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Title</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($recent as $row): ?><tr><td><a class="complaint-id" href="<?= e(url('student/complaint.php?id='.$row['id'])) ?>"><?= e($row['complaint_id']) ?></a></td><td><?= e($row['title']) ?><div class="small-muted"><?= e($row['category_name']) ?></div></td><td><span class="badge-soft <?= e(status_class($row['status'])) ?>"><?= e($row['status']) ?></span></td><td class="small-muted"><?= e(date('d M Y', strtotime($row['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></div>
